package com.lingualearn.app.data.content

/**
 * Malayalam (ml), Dutch (nl), and Swedish (sv) comprehensive curriculum content.
 * 10 levels × 6 topics = 60 distinct lessons per language.
 */
object MalayalamCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("നമസ്കാരം! / സുപ്രഭാതം", "Namaskaram! / Good morning", "nuh-muhs-KAA-ruhm / soo-pruh-BHAA-thuhm", "നമസ്കാരം! സുഖമാണോ?", "Namaskaram! Are you well / How are you?", "The respectful traditional greeting honoring the divine within.")
                "Introducing Yourself" -> CurriculumLessonContent("എന്റെ പേര് രാഹുൽ എന്നാണ്", "My name is Rahul", "EN-tay PAY-roo RAA-hool EN-naan", "എന്റെ പേര് രാഹുൽ, ഞാൻ കേരളത്തിൽ നിന്നാണ്.", "My name is Rahul, I am from Kerala.", "'Ente peru' (my name) is the standard polite introduction.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("അതെ / അല്ല / ദയവായി / നന്ദി", "Yes / No / Please / Thank you", "uh-DHAY / UHL-luh / duh-yuh-VAA-yee / NUHN-nee", "അതെ, ദയവായി സഹായിക്കാമോ? വളരെ നന്ദി!", "Yes, could you please help? Thank you very much!", "'Nanni' expresses sincere, heartfelt gratitude.")
                "Numbers 1–10" -> CurriculumLessonContent("ഒന്ന്, രണ്ട്, മൂന്ന്, നാല്, അഞ്ച്...", "1 to 10 numerals", "OHN-noo, RAHN-doo, MOON-noo", "രണ്ട് കപ്പ് ചായ തരൂ, ദയവായി.", "Two cups of tea, please.", "Tea stalls ('Chayakada') across Kerala count in these numbers.")
                "Basic Pronouns" -> CurriculumLessonContent("ഞാൻ, നീ, നിങ്ങൾ, ഞങ്ങൾ, അവർ", "I, you (inf), you (formal), we, they", "NJAAN, nee, NEENG-nguhl, NYUNG-nguhl, uh-VUHR", "ഞങ്ങൾ ഒരുമിച്ച് മലയാളം പഠിക്കുകയാണ്.", "We are learning Malayalam together.", "'Ningal' is respectful and polite; 'nee' is for close younger peers.")
                else -> CurriculumLessonContent("ക്ഷമിക്കണം ഒപ്പം വീണ്ടും കാണാം", "Excuse me / Sorry and See you again", "kshu-MEEK-kuh-nuhm / VEEN-doom KAA-naam", "ക്ഷമിക്കണം, റെയിൽവേ സ്റ്റേഷൻ എവിടെയാണ്?", "Excuse me, where is the railway station located?", "'Veendum kaanaam' is the warm farewell phrase.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("കുടുംബം (അമ്മ, അച്ഛൻ, ചേട്ടൻ, ചേച്ചി)", "Family (mother, father, elder brother, elder sister)", "koo-DOOM-buhm", "എന്റെ ചേട്ടൻ കൊച്ചിയിൽ ജോലി ചെയ്യുന്നു.", "My elder brother works in Kochi.", "Malayalam distinguishes elder (chettan/chechi) and younger (aniyan/aniyathi) siblings.")
                "Colors" -> CurriculumLessonContent("ചുവപ്പ്, നീല, മഞ്ഞ, പച്ച, വെള്ള", "Red, Blue, Yellow, Green, White", "choo-VUHP-poo, NEE-luh, MUHN-nyuh", "ആ പച്ച സാരി വളരെ മനോഹരമാണ്.", "That green saree is very beautiful.", "Color words precede nouns naturally.")
                "Food" -> CurriculumLessonContent("സദ്യ, ചോറ്, സാമ്പാർ, കട്ടൻചായ", "Sadya, rice, sambar, and black tea", "SUHD-yuh, CHOH-roo, SAAM-baar", "ഓണസദ്യ വാഴയിലയിൽ കഴിക്കുന്നത് അതിവിശിഷ്ടമാണ്.", "Eating Onam feast (Sadya) on a banana leaf is exquisite.", "Kerala Sadya features up to 26 vegetarian delicacies.")
                "Days & Months" -> CurriculumLessonContent("തിങ്കൾ മുതൽ ഞായർ വരെ", "Monday to Sunday", "THEENG-guhl moo-dhal NYAA-yuhr", "ഞായറാഴ്ച ഞങ്ങൾ ആലപ്പുഴയിലേക്ക് യാത്ര പോകും.", "On Sunday we will take a trip to Alappuzha.", "Malayalam calendar days mirror traditional planetary names.")
                "Simple Questions" -> CurriculumLessonContent("ആര്? എന്ത്? എവിടെ? എപ്പോൾ? എന്തുകൊണ്ട്?", "Who? What? Where? When? Why?", "AAR-oo, EN-thoo, eh-vee-DAY, ehp-POHL", "ബസ് സ്റ്റാൻഡ് എവിടെയാണെന്ന് പറയാമോ?", "Could you tell me where the bus stand is?", "Question words in Malayalam often begin with the vowel 'e'.")
                else -> CurriculumLessonContent("കഴിക്കുക, കുടിക്കുക, വരിക, പോവുക", "Eat, drink, come, go", "kuh-ZHEEK-koo-kuh, koo-DEEK-koo-kuh", "വൈകുന്നേരം സുഹൃത്തുക്കളോടൊപ്പം കടൽത്തീരത്ത് പോകുന്നു.", "In the evening I go to the beach with friends.", "Infinitive verbs in Malayalam end in '-uka'.")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("പ്രഭാത നടത്തവും ദിനചര്യയും", "Morning walk and daily routine", "pruh-BHAA-thuh nuh-DUHT-thuhm", "ഞാൻ എല്ലാ ദിവസവും രാവിലെ ആറുമണിക്ക് ഉണരും.", "I wake up at six o'clock every morning.", "Present habitual verbs end in '-unnu'.")
                "Shopping" -> CurriculumLessonContent("ഇതിന് എന്ത് വിലയാകും?", "How much does this cost?", "ee-THEEN-oo enthoo vee-luh-YAA-goom", "ചേട്ടാ, ഈ കസവു മുണ്ടിന് എന്ത് വിലയാകും?", "Brother, how much is this Kasavu mundu?", "Addressing shopkeepers as 'Chetta' (elder brother) creates immediate warmth.")
                "Time" -> CurriculumLessonContent("ഇപ്പോൾ സമയം എത്രയായി?", "What is the time now?", "eep-POHL suh-muh-yuhm", "ഇപ്പോൾ ഉച്ചകഴിഞ്ഞ് രണ്ടര മണിയായി.", "It is 2:30 in the afternoon right now.", "'Randara' signifies half past two (2:30).")
                "Directions" -> CurriculumLessonContent("നേരെ പോയി വലത്തോട്ട് തിരിയുക", "Go straight and turn right", "NAY-ray POH-yee, vuhl-UHTH-thoht", "നേരെ മുന്നോട്ട് പോയി ജംഗ്ഷനിൽ ഇടത്തോട്ട് തിരിയുക.", "Go straight ahead and turn left at the junction.", "'Valathottu' is right, 'idathottu' is left.")
                "Simple Sentences" -> CurriculumLessonContent("എനിക്ക് ഒരു കട്ടൻചായ വേണം", "I want a black tea", "kuh-TUN-chaa-yuh VAY-nuhm", "വൈകുന്നേരം കായലോരത്ത് നടക്കാൻ എനിക്ക് ആഗ്രഹമുണ്ട്.", "I desire to walk along the backwaters in the evening.", "'Veenam' means want/need; 'aagrahamundu' means desire.")
                else -> CurriculumLessonContent("വിശേഷങ്ങൾ എന്തൊക്കെയാണ്?", "What's the latest news with you?", "vee-SHAY-shung-nguhl en-thohk-kay", "എല്ലാം സുഖമായി പോകുന്നു, ദൈവകൃപ!", "Everything is going smoothly, by God's grace!", "Classic warm Malayali check-in phrase.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("ഇന്നലെ ഞാൻ കോവളം ബീച്ചിൽ പോയി", "Yesterday I went to Kovalam Beach", "EEN-nuh-lay njaan KOH-vuh-luhm", "ഇന്നലെ മനോഹരമായ സൂര്യാസ്തമയം ഞങ്ങൾ കണ്ടു.", "Yesterday we watched the gorgeous sunset.", "Past tense markers indicate completed actions: 'poyi' (went).")
                "Future Plans" -> CurriculumLessonContent("അടുത്ത മാസം മൂന്നാറിലേക്ക് യാത്ര ചെയ്യും", "Next month we will travel to Munnar", "UH-dhoot-thuh MAA-suhm", "അവധിക്കാലത്ത് ഞങ്ങൾ തേയിലത്തോട്ടങ്ങൾ സന്ദർശിക്കും.", "During vacation we will visit the lush tea plantations.", "Future tense conjugations express pleasant travel anticipation.")
                "Travel" -> CurriculumLessonContent("കെട്ടുവള്ളവും കായൽയാത്രയും", "Houseboat and backwater cruise", "KET-too-vuhl-luhm", "ആലപ്പുഴയിലെ ഹൗസ്ബോട്ട് യാത്ര അതിമനോഹരമാണ്.", "The houseboat cruise in Alappuzha is breathtaking.", "Traditional kettuvallams are hand-woven with coir knots.")
                "Restaurants" -> CurriculumLessonContent("ബിൽ കൊണ്ടുവരൂ, ദയവായി", "Please bring the bill", "bil kohn-doo-vuh-ROO", "ഭക്ഷണം വളരെ സ്വാദിഷ്ടമായിരുന്നു, ബിൽ തരുമോ?", "The meal was very delicious, could you give the bill?", "Appam and stew or Kerala fish curry highlight the meal.")
                "Describing People" -> CurriculumLessonContent("സ്നേഹസമ്പന്നനായ, വിശ്വസ്തനായ സുഹൃത്ത്", "Loving and trustworthy friend", "snay-huh-suhm-PUHN-nuh-nuh-yuh", "എന്റെ അധ്യാപകൻ എപ്പോഴും ക്ഷമയുള്ളവനും ദയാലുവുമാണ്.", "My teacher is always patient and compassionate.", "Adjectives in Malayalam naturally end in '-aaya'.")
                else -> CurriculumLessonContent("ഇന്ന് നല്ല കുളിർമയുള്ള കാലാവസ്ഥയാണ്", "Today the weather is pleasantly cool", "koo-LEER-muh-yool-luh", "തുലാവർഷം പെയ്തൊഴിഞ്ഞപ്പോൾ നാടെങ്ങും കുളിർമയായി.", "With the monsoon rains subsiding, the entire land is cool.", "Kerala's lush monsoons are deeply tied to nature and literature.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("എന്റെ അഭിപ്രായം കൂടി പറയാമോ?", "May I share my opinion as well?", "uh-bhee-PRAA-yuhm", "ഈ വിഷയത്തിൽ ചില പ്രായോഗിക നിർദ്ദേശങ്ങൾ മുന്നോട്ട് വെക്കട്ടെ?", "May I put forward some practical suggestions on this matter?", "Polite formal conversational participation.")
                "Opinions" -> CurriculumLessonContent("എന്റെ കാഴ്ചപ്പാടിൽ പ്രകൃതിസംരക്ഷണം", "In my perspective, nature conservation", "KAAZH-chuh-ppaa-deel", "എന്റെ കാഴ്ചപ്പാടിൽ, പ്രകൃതിയോട് ഇണങ്ങി ജീവിക്കലാണ് പരമപ്രധാനം.", "In my view, living in harmony with nature is of paramount importance.", "'Ente kaazhchappaadil' introduces grounded viewpoints.")
                "Experiences" -> CurriculumLessonContent("മറക്കാനാവാത്ത ജീവിതാനുഭവങ്ങൾ", "Unforgettable life experiences", "muh-ruhk-kaan-AA-vaa-thuh", "വയനാട്ടിലെ മലനിരകളിലൂടെയുള്ള യാത്ര മറക്കാനാവാത്തതായിരുന്നു.", "The journey through Wayanad hills was completely unforgettable.", "Sharing reflective travel memories.")
                "Comparisons" -> CurriculumLessonContent("കൊച്ചിയേക്കാൾ ശാന്തമാണ് കോട്ടയം", "Kottayam is calmer than Kochi", "KOHCH-chee-yek-kaal", "ഗ്രാമീണ ജീവിതം നഗരജീവിതത്തേക്കാൾ പ്രശാന്തമാണ്.", "Village life is far more tranquil than city life.", "The suffix '-ekkaal' marks comparative evaluation.")
                "More Complex Grammar" -> CurriculumLessonContent("എങ്കിൽ... എങ്കിൽ മാത്രമേ (വ്യവസ്ഥകൾ)", "If... only if (conditionals)", "ENG-geel ... ENG-geel MAA-thruh-may", "കഠിനാധ്വാനം ചെയ്തെങ്കിൽ മാത്രമേ വിജയം കൈവരിക്കാനാവൂ.", "Only if one works hard can success be attained.", "Conditional markers link effort and consequence.")
                else -> CurriculumLessonContent("മലയാളം വാർത്തകൾ കേൾക്കൽ പരിശീലനം", "Malayalam news listening practice", "VAAR-thuh-kuhl KAYL-kkuhl", "ആകാശവാണി വാർത്തകൾ കേട്ട് ഉച്ചാരണശുദ്ധി വർദ്ധിപ്പിക്കുക.", "Improving phonetic clarity by listening to All India Radio news.", "Pay attention to retroflex consonants (zh, l, n, r).")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("ഒരിടത്തൊരിടത്ത് ഒരു ഗ്രാമത്തിൽ...", "Once upon a time in a village...", "oh-ree-duht-thoh-ree-duht-thoo", "ഐതിഹ്യമാലയിലെ അത്ഭുതകഥകൾ തലമുറകളിലേക്ക് പകർന്നു നൽകപ്പെട്ടു.", "Miraculous tales of Aithihyamala were passed down generations.", "Aithihyamala preserves Kerala's rich folkloric mythology.")
                "Workplace Conversations" -> CurriculumLessonContent("ഔദ്യോഗിക മീറ്റിംഗും ചർച്ചകളും", "Official meeting and discussions", "owd-YOH-gee-kuh", "പുതിയ പദ്ധതിയുടെ പുരോഗതി ഞങ്ങൾ വിശദമായി വിലയിരുത്തി.", "We comprehensively evaluated the progress of the new project.", "Professional Malayalam thrives across modern enterprises.")
                "Social Situations" -> CurriculumLessonContent("വിരുന്നോമ്പലും സ്നേഹോഷ്മളമായ സ്വീകരണവും", "Hospitality and warm reception", "vee-ROON-nohm-buh-loom", "ഞങ്ങളുടെ വീട്ടിലേക്ക് കടന്നുവന്നതിന് ഹൃദയം നിറഞ്ഞ നന്ദി.", "Heartfelt gratitude for gracing our home with your visit.", "Guests are welcomed with profound warmth in Kerala.")
                "News & Media" -> CurriculumLessonContent("പത്രവാർത്തകളും മുഖപ്രസംഗവും", "Newspaper reports and editorials", "PUHTH-ruh-vaar-thuh-kuhl", "മലയാള മനോരമയിലെ മുഖപ്രസംഗം സാമൂഹിക മാറ്റങ്ങളെ വിശകലനം ചെയ്യുന്നു.", "The editorial in Malayala Manorama analyzes social changes.", "Kerala holds India's highest literacy rate and newspaper readership.")
                "Idiomatic Expressions" -> CurriculumLessonContent("മുല്ലപ്പൂമ്പൊടിയേറ്റു കിടക്കും കല്ലിനുമുണ്ടാകും സൗരഭ്യം", "Stone touched by jasmine dust also gains fragrance", "MOOL-luh-ppoom-boh-dee", "നല്ല സൗഹൃദങ്ങൾ വ്യക്തിത്വത്തിന് മാറ്റ് കൂട്ടും.", "Good company elevates one's character.", "Classic Malayalam poetic proverb celebrating noble company.")
                else -> CurriculumLessonContent("പ്രത്യയങ്ങളും വിഭക്തികളും", "Suffixes and case markers in grammar", "pruht-yuh-YUNG-nguhl", "കാരകങ്ങളും വിഭക്തി പ്രത്യയങ്ങളും ശരിയായി പ്രയോഗിക്കുക.", "Correctly deploying noun case suffixes.", "Malayalam employs agglutinative postpositional case endings.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("നവോത്ഥാന ചിന്തകളും സാമൂഹിക മുന്നേറ്റവും", "Renaissance thought and social progress", "nuh-voht-THAA-nuh", "ശ്രീനാരായണഗുരുവിന്റെ മാനവിക ദർശനങ്ങൾ കേരളത്തെ മാറ്റിമറിച്ചു.", "Sree Narayana Guru's humanistic philosophy transformed Kerala.", "Articulating social reform themes in cultured Malayalam.")
                "Debate & Opinions" -> CurriculumLessonContent("സഭ്യമായ വിയോജിപ്പും സംവാദവും", "Civil disagreement and debate", "SUHB-yuh-maa-nuh", "നിങ്ങളുടെ വാദങ്ങളെ മാനിച്ചുകൊണ്ടുതന്നെ ഞാൻ മറ്റൊരു വശം ചൂണ്ടിക്കാണിക്കുന്നു.", "Respecting your arguments, I point out another dimension.", "Civilized debating etiquette.")
                "Abstract Topics" -> CurriculumLessonContent("കേരളീയ പാരമ്പര്യവും പ്രകൃതിബോധവും", "Kerala heritage and ecological consciousness", "kay-ruh-LEE-yuh", "പ്രകൃതിയെ അമ്മയായി കണ്ടുകൊണ്ടുള്ള ജീവനരീതി.", "A way of life viewing nature as a nurturing mother.", "Ecological harmony embedded in folk tradition.")
                "Natural Expressions" -> CurriculumLessonContent("കണ്ണിൽ എണ്ണയൊഴിച്ചു കാത്തിരിക്കുക", "Wait with oil in eyes (wait with keen vigilance)", "KUHN-neel EN-nuh", "പരീക്ഷാഫലത്തിനായി വിദ്യാർത്ഥികൾ ആകാംക്ഷയോടെ കാത്തിരിക്കുന്നു.", "Students wait eagerly and keenly for exam results.", "Expressive colloquial idioms.")
                "Listening Comprehension" -> CurriculumLessonContent("സാഹിത്യ പ്രഭാഷണങ്ങൾ ശ്രദ്ധാപൂർവ്വം കേൾക്കൽ", "Attentively listening to literary lectures", "SAA-heet-yuh pruh-BHAA-shuh-nuhm", "പണ്ഡിതോചിതമായ പ്രസംഗങ്ങളിലെ ഭാഷാസൗന്ദര്യം ആസ്വദിക്കുക.", "Savoring linguistic beauty in scholarly public lectures.", "Comprehending rapid spoken oratorical Malayalam.")
                else -> CurriculumLessonContent("ഗവേഷണ പ്രബന്ധ രചന", "Research essay composition", "guh-VAY-shuh-nuh pruh-BUHN-dhuhm", "വ്യക്തമായ ആമുഖവും യുക്തിഭദ്രമായ നിഗമനങ്ങളുമുള്ള ലേഖനം.", "An essay with clear introduction and logically sound conclusions.", "Scholarly prose standards.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("തന്ത്രപരമായ ആസൂത്രണവും നയരൂപീകരണവും", "Strategic planning and policymaking", "thuhn-thruh-puh-ruh-maa-nuh", "ദീർഘകാല നേട്ടങ്ങൾ മുൻനിർത്തിക്കൊണ്ടുള്ള സമഗ്രമായ നയരൂപീകരണം.", "Comprehensive policymaking prioritizing long-term gains.", "Executive administrative vocabulary.")
                "Cultural Context" -> CurriculumLessonContent("കഥകളിയും കൂടിയാട്ടവും ശാസ്ത്രീയ കലകളും", "Kathakali, Koodiyattam, and classical arts", "kuh-thuh-KAH-lee", "കഥകളിയുടെ മുദ്രകളും ഭാവപ്രകടനങ്ങളും വിശ്വോത്തര കലാരൂപമാണ്.", "Kathakali's mudras and expressions are a world-renowned art form.", "Koodiyattam is recognized by UNESCO as intangible world heritage.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("അനന്യമായ, സുഭഗമായ, അനിർവ്വചനീയമായ", "Unmatched, graceful, and indescribable", "uh-nuhn-yuh-MAA-nuh", "സന്ധ്യാസമയത്തെ കായൽക്കാഴ്ച അനിർവ്വചനീയമായ സൗന്ദര്യം പകരുന്നു.", "The backwater view at twilight imparts indescribable beauty.", "Elevated classical vocabulary.")
                "Advanced Listening" -> CurriculumLessonContent("പ്രാദേശിക ഭാഷാഭേദങ്ങൾ തിരിച്ചറിയൽ", "Identifying regional Malayalam dialects", "praa-dhay-shee-kuh", "വള്ളുവനാടൻ, തെക്കൻ, മലബാർ ശൈലികളുടെ തനത് ശീലുകൾ.", "Unique melodic inflections of Valluvanadan, Southern, and Malabar dialects.", "Appreciating dialectal diversity across Kerala.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("സാഹിത്യഭാഷയും ദൈനംദിന സംസാരഭാഷയും", "Literary prose vs Everyday spoken tongue", "SAA-heet-yuh BHAASH-uh", "ഔദ്യോഗിക സന്ദർഭങ്ങളിലെ ഗൗരവപൂർണ്ണമായ ഭാഷാപ്രയോഗം.", "Dignified linguistic deployment in formal occasions.", "Shifting registers with ease.")
                else -> CurriculumLessonContent("മണിപ്രവാള ശൈലിയും തുഞ്ചൻ എഴുത്തച്ഛനും", "Manipravalam style and Thunchath Ezhuthachan", "eh-zhoot-THUH-chuhn", "ആധുനിക മലയാള ഭാഷയുടെ പിതാവായ എഴുത്തച്ഛന്റെ കിളിപ്പാട്ടുകൾ.", "Kilippattu works of Ezhuthachan, the father of modern Malayalam.", "Foundational roots of Malayalam poetry.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("അന്താരാഷ്ട്ര വാണിജ്യ ഉടമ്പടികൾ", "International commercial treaties", "uhn-thuh-RAASH-truh", "ഇരു കമ്പനികളും തന്ത്രപരമായ സംയുക്ത സംരംഭത്തിൽ ഒപ്പുവെച്ചു.", "Both companies signed the strategic joint venture pact.", "High corporate, maritime, and legal Malayalam.")
                "Advanced Reading" -> CurriculumLessonContent("എം.ടി. വാസുദേവൻ നായരും ഒ.വി. വിജയനും", "M.T. Vasudevan Nair and O.V. Vijayan", "em-tee vaa-soo-DAY-vuhn", "ഖസാക്കിന്റെ ഇതിഹാസം മലയാള നോവൽ സാഹിത്യത്തിലെ നാഴികക്കല്ലാണ്.", "The Legends of Khasak is an epochal milestone in Malayalam literature.", "Reading acclaimed masterworks.")
                "Idioms & Expressions" -> CurriculumLessonContent("ചക്കരക്കുടത്തിൽ കൈയിട്ടതുപോലെ", "Like putting hand in a pot of jaggery (immense delight)", "CHUK-kuh-ruh-kkoo-duhm", "അപ്രതീക്ഷിത വിജയം അവന് അളവറ്റ സന്തോഷം നൽകി.", "Unexpected victory brought him boundless sweet delight.", "Picturesque traditional idioms.")
                "Advanced Writing" -> CurriculumLessonContent("ഗവേഷണ പ്രബന്ധങ്ങളും വിമർശനങ്ങളും", "Research monographs and critical critiques", "vee-muhr-SHUH-nung-nguhl", "വിഷയത്തെ സമഗ്രമായി അപഗ്രഥിച്ചുകൊണ്ടുള്ള പ്രൗഢമായ ലേഖനം.", "A majestic essay analyzing the subject with comprehensive depth.", "Scholarly prose composition.")
                "Difficult Listening" -> CurriculumLessonContent("നിയമസഭാ ചർച്ചകളും തത്സമയ സംവാദങ്ങളും", "Legislative assembly debates and live deliberations", "nee-yuh-muh-SUH-bhaa", "മിന്നൽവേഗത്തിലുള്ള രാഷ്ട്രീയ സംവാദങ്ങൾ തത്സമയം ഗ്രഹിക്കുക.", "Comprehending lightning-fast political debate in real time.", "Supreme acoustic discernment.")
                else -> CurriculumLessonContent("മാതൃഭാഷാ സമഗ്രാധിപത്യം", "Native linguistic sovereignty and eloquence", "MAA-truh-bhaash-aa", "ഏതു സങ്കീർണ്ണ വിഷയത്തിലും ഗഹനവും ലളിതവുമായി സംസാരിക്കാനുള്ള കഴിവ്.", "Ability to speak profoundly and lucidly on any complex topic.", "Complete bilingual mastery.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("സ്വാഭാവികവും സരളവുമായ സംഭാഷണം", "Natural and effortless fluent conversation", "swaa-BHAA-vee-kuhm", "തടസ്സമില്ലാതെ ശുദ്ധമലയാളത്തിൽ മനോഹരമായി സംസാരിക്കുക.", "Speaking beautifully in pure Malayalam without the slightest hesitation.", "Native cadence and charm.")
                "Humor & Cultural References" -> CurriculumLessonContent("കുഞ്ചൻ നമ്പ്യാരുടെ തുള്ളൽ ഹാസ്യം", "Kunchan Nambiar's Thullal satire and wit", "KOON-chuhn nuhm-BYAAR", "നർമ്മത്തിലൂടെയുള്ള സാമൂഹിക വിമർശനങ്ങൾ പൂർണ്ണമായി ആസ്വദിക്കുക.", "Wholeheartedly savoring satirical social critiques through humor.", "Culturally grounded humor.")
                "Advanced Debates" -> CurriculumLessonContent("വാഗ്മിതയും ആശയപ്രകടനവും", "Commanding oratorical brilliance and rhetoric", "VAAG-mee-thuh", "ശക്തമായ യുക്തിയും വാക്ചാതുരിയും കൊണ്ട് സദസ്സിനെ ആകർഷിക്കുക.", "Captivating the audience with compelling logic and verbal eloquence.", "Mastery over public oratory.")
                "Professional Fluency" -> CurriculumLessonContent("ആഗോള തലത്തിലെ പ്രവാസി നേതൃത്വം", "Leadership across the global Malayali diaspora", "proo-VAA-see", "അന്താരാഷ്ട്ര വേദികളിൽ കേരളത്തിന്റെ സംസ്കാരം ഉയർത്തിപ്പിടിക്കുക.", "Upholding Kerala's culture with distinction on international stages.", "Executive leadership across the diaspora.")
                "Native-Speed Listening" -> CurriculumLessonContent("സൂക്ഷ്മശ്രവണ നൈപുണ്യം", "Acute auditory discernment at native speed", "SOOK-shmuh-shruh-vuh-nuhm", "വേഗത്തിലുള്ള സംഭാഷണങ്ങളിലെ ധ്വനികളും അർത്ഥതലങ്ങളും പിടിച്ചെടുക്കുക.", "Catching subtexts and hidden depths even in rapid-fire dialogue.", "Total acoustic mastery.")
                else -> CurriculumLessonContent("മലയാള ഭാഷാ സംസ്കാര സംയോജനം", "Complete cultural and linguistic oneness with Malayalam", "suhm-YOH-juh-nuhm", "മലയാളത്തിന്റെ മാധുര്യവും സാംസ്കാരിക പൈതൃകവും ജീവിതമാക്കുക.", "Living the sweetness and cultural heritage of Malayalam completely.", "Ultimate linguistic and cultural mastery.")
            }
        }
    }
}

object DutchCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("Hallo! / Goedemorgen / Goedemiddag", "Hello! / Good morning / Good afternoon", "HAH-loh / KHOO-duh-MOR-khen", "Goedemorgen! Hoe gaat het met u?", "Good morning! How are you doing? (polite)", "'Gezellig' is the iconic Dutch cultural concept of cozy, warm togetherness.")
                "Introducing Yourself" -> CurriculumLessonContent("Ik heet Daan, aangenaam kennis te maken", "My name is Daan, pleased to meet you", "ik hayt daan, AHN-khuh-nahm", "Ik heet Daan en ik kom uit Amsterdam.", "My name is Daan and I come from Amsterdam.", "'Aangenaam' is the classic polite response when introduced.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("Ja / Nee / Alstublieft / Dank u wel", "Yes / No / Please / Thank you", "yah / nay / AHLST-oo-bleeft / dahngk oo vel", "Ja, alstublieft! Hartelijk dank voor de hulp.", "Yes, please! Heartfelt thanks for the help.", "Use 'alstublieft' formally, and 'alsjeblieft' informally.")
                "Numbers 1–10" -> CurriculumLessonContent("Een, twee, drie, vier, vijf...", "1 to 10 numerals", "ayn, tvay, dree, veer, vyf", "Twee koppen koffie en een stroopwafel, alstublieft.", "Two cups of coffee and a stroopwafel, please.", "Warm stroopwafels over steaming coffee are a Dutch ritual.")
                "Basic Pronouns" -> CurriculumLessonContent("Ik, jij, hij, zij, wij, jullie, zij", "I, you, he, she, we, y'all, they", "ik, yay, hay, zay, way, YOOL-lee, zay", "Wij leren samen de Nederlandse taal.", "We are learning the Dutch language together.", "Pronouns have reduced spoken forms: 'je', 'ze', 'we'.")
                else -> CurriculumLessonContent("Pardon en Tot ziens", "Excuse me and Goodbye", "par-DOHN / tot zeens", "Pardon, waar is het Centraal Station?", "Excuse me, where is the Central Station located?", "'Tot ziens' literally means 'until we see each other'.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("De familie (ouders, broer, zus)", "Family (parents, brother, sister)", "duh fah-MEE-lee", "Mijn broer woont in Utrecht en mijn zus in Den Haag.", "My brother lives in Utrecht and my sister in The Hague.", "Dutch nouns take either 'de' or 'het' as definite article.")
                "Colors" -> CurriculumLessonContent("Rood, wit, blauw, oranje, groen", "Red, White, Blue, Orange, Green", "roht, vit, blow, oh-RAHN-yuh, khroon", "Oranje is de nationale kleur van Nederland.", "Orange is the national color of the Netherlands.", "Orange celebrates the royal House of Orange-Nassau.")
                "Food" -> CurriculumLessonContent("Kaas, haring en stamppot", "Cheese, herring, and stamppot", "kahs, HAH-ring, STAHM-pot", "Goudse kaas en verse stroopwafels zijn wereldberoemd.", "Gouda cheese and fresh stroopwafels are world-famous.", "Stamppot (mashed potatoes with kale and smoked sausage) warms winter nights.")
                "Days & Months" -> CurriculumLessonContent("Maandag tot en met Zondag", "Monday through Sunday", "MAHN-dahkh tot en met ZOHN-dahkh", "Zaterdag gaan we fietsen langs de grachten.", "On Saturday we are going cycling along the canals.", "Bicycle paths ('fietspad') crisscross every Dutch town.")
                "Simple Questions" -> CurriculumLessonContent("Wie? Wat? Waar? Wanneer? Waarom?", "Who? What? Where? When? Why?", "vee, vaht, vahr, vah-NAYR, vah-ROHM", "Waarom leer je Nederlands?", "Why are you learning Dutch?", "In Dutch main clauses, the conjugated verb occupies the second position.")
                else -> CurriculumLessonContent("Eten, drinken, gaan, komen", "Eat, drink, go, come", "AY-ten, DRING-ken, khahn, KOH-men", "Zullen we samen een kopje koffie gaan drinken?", "Shall we go drink a cup of coffee together?", "Irregular past tense (at, dronk, ging, kwam).")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("Vroeg opstaan en fietsen naar het werk", "Waking up early and cycling to work", "vrookh OHP-stahn", "Ik sta om zeven uur op en fiets naar mijn werk.", "I get up at seven o'clock and cycle to my work.", "'Opstaan' is separable: 'sta ... op'.")
                "Shopping" -> CurriculumLessonContent("Hoeveel kost dit?", "How much does this cost?", "HOO-vayl kohst dit", "Pardon, hoeveel kost deze bos tulpen?", "Excuse me, how much does this bunch of tulips cost?", "Flower markets (Bloemenmarkt) line city squares.")
                "Time" -> CurriculumLessonContent("Hoe laat is het?", "What time is it?", "hoo LAHT is het", "Het is half drie in de middag.", "It is half to three (2:30) in the afternoon.", "Dutch 'half drie' means 2:30 (half an hour before 3).")
                "Directions" -> CurriculumLessonContent("Rechtdoor en rechtsaf slaan", "Straight ahead and turn right", "rekht-DOHR / rekhts-AHF", "Ga rechtdoor en sla bij de brug linksaf.", "Go straight ahead and turn left at the bridge.", "'Rechts' is right, 'links' is left.")
                "Simple Sentences" -> CurriculumLessonContent("Ik wil graag een fiets huren", "I would like to rent a bicycle", "ik vil khrahkh ayn feets HOO-ren", "Ik wil graag een dagkaart voor de trein kopen.", "I would like to buy a day ticket for the train.", "'Ik wil graag' is the polite way to say 'I would like'.")
                else -> CurriculumLessonContent("Hoe gaat het ermee? Alles goed?", "How's it going? Everything good?", "hoo kHAHT het / AHL-les khoot", "Alles prima, dank je! En met jou?", "Everything's fine, thanks! And with you?", "Friendly casual Dutch check-in.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("Gisteren heb ik het Rijksmuseum bezocht", "Yesterday I visited the Rijksmuseum", "KHEES-ter-en hep ik", "Gisteren hebben we de Nachtwacht van Rembrandt bewonderd.", "Yesterday we admired Rembrandt's Night Watch.", "Voltooid tegenwoordige tijd uses hebben or zijn + voltooid deelwoord.")
                "Future Plans" -> CurriculumLessonContent("Ik ga volgend jaar reizen", "I am going to travel next year", "ik khah VOHL-khend yahr", "Volgende maand ga ik naar de Waddeneilanden.", "Next month I am going to the Wadden Islands.", "'Gaan + infinitive' forms the near future.")
                "Travel" -> CurriculumLessonContent("De OV-chipkaart en de NS-trein", "Transit chip card and Dutch Railways train", "OH-vay CHIP-kahrt", "Vergeet niet in en uit te checken met je OV-chipkaart.", "Don't forget to check in and out with your transit card.", "The OV-chipkaart works across all Dutch public transport.")
                "Restaurants" -> CurriculumLessonContent("Mag ik de rekening, alstublieft?", "May I have the bill, please?", "mahkh ik duh RAY-kuh-ning", "Het eten was heerlijk, mag ik de rekening alstublieft?", "The meal was delicious, may I have the bill please?", "'Gaan we pinnen?' asks if you pay by debit card.")
                "Describing People" -> CurriculumLessonContent("Vriendelijk, nuchter en behulpzaam", "Friendly, down-to-earth, and helpful", "NOOKH-ter / buh-HOOLP-zahm", "Nederlanders staan bekend om hun nuchtere mentaliteit.", "Dutch people are renowned for their down-to-earth mentality.", "'Nuchter' describes practical, unpretentious common sense.")
                else -> CurriculumLessonContent("Mooi weer vandaag, vind je niet?", "Nice weather today, don't you think?", "moy vayr vahn-DAHKH", "Het zonnetje schijnt heerlijk op het terras.", "The sun is shining delightfully on the café terrace.", "'Terrasje pakken' (grabbing a café patio seat) is beloved in sunny weather.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("Mag ik daar iets aan toevoegen?", "May I add something to that?", "mahkh ik dahr eets", "Mag ik even inhaken op wat u net zei?", "May I briefly hook into what you just said?", "Polite participative conversational formulas.")
                "Opinions" -> CurriculumLessonContent("Naar mijn mening", "In my opinion", "nahr myn MAY-ning", "Naar mijn mening moeten we meer investeren in duurzaamheid.", "In my opinion, we must invest more in sustainability.", "'Naar mijn mening' introduces viewpoints smoothly.")
                "Experiences" -> CurriculumLessonContent("Een onvergetelijke ervaring", "An unforgettable experience", "ayn ohn-ver-KHAY-tuh-luh-kuh", "Schaatsen op natuurijs was een onvergetelijke belevenis.", "Ice skating on natural frozen canals was unforgettable.", "Ice skating on natural ice is the Dutch national winter passion.")
                "Comparisons" -> CurriculumLessonContent("Veel beter dan / Even goed als", "Much better than / Just as good as", "vayl BAY-ter dahn", "Reizen met de trein is veel milieuvriendelijker dan vliegen.", "Traveling by train is much more environmentally friendly than flying.", "Use 'dan' with comparatives, 'als' with equality.")
                "More Complex Grammar" -> CurriculumLessonContent("Bijzinnen met Omdat en Dat", "Subordinate clauses with Because and That", "BY-zin-nen", "Ik leer Nederlands omdat ik hier wil studeren.", "I am learning Dutch because I want to study here.", "In Dutch subordinate clauses, all verbs move to the very end.")
                else -> CurriculumLessonContent("Nederlandse luistervaardigheid oefenen", "Practicing Dutch listening skills", "LOYS-ter-vahr-dikh-heyt", "Luisteren naar NPO Radio om de natuurlijke intonatie te leren.", "Listening to NPO Radio to master natural cadence.", "Pay attention to guttural 'g' and diphthongs (ui, ei, ij).")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("Er was eens lang geleden...", "Once upon a time long ago...", "er vahs ayns lahng khuh-LAY-den", "Plotseling verscheen er een geheimzinnig licht in de duinen.", "Suddenly a mysterious light appeared in the dunes.", "Classic narrative formula in Dutch fairy tales.")
                "Workplace Conversations" -> CurriculumLessonContent("De vergadering en het poldermodel", "The meeting and the polder model consensus", "ver-KHAH-duh-ring", "We moeten polderen om tot een breed gedragen compromis te komen.", "We must consensus-build ('polder') to reach a widely supported compromise.", "The Dutch 'poldermodel' seeks pragmatic consensus through dialogue.")
                "Social Situations" -> CurriculumLessonContent("Bedankt voor de gezellige avond", "Thank you for the cozy, wonderful evening", "khuh-ZEL-lee-khuh", "Het was ontzettend gezellig, bedankt voor de gastvrijheid!", "It was tremendously cozy; thank you for the hospitality!", "'Gezellig' is the ultimate compliment for a host.")
                "News & Media" -> CurriculumLessonContent("Het nieuws van de dag en commentaar", "News of the day and commentary", "KHOOR-nuhl", "Het NOS Journaal brengt verslag uit over de formatie.", "The NOS news reports on cabinet formation negotiations.", "Journalistic Dutch is direct and lucid.")
                "Idiomatic Expressions" -> CurriculumLessonContent("Helaas pindakaas / Nu komt de aap uit de mouw", "Too bad peanut butter / Now truth emerges", "hay-LAHS PIN-dah-kahs", "Nu komt de aap uit de mouw: hij had toch een ander plan.", "Now the monkey comes out of the sleeve: he had another plan after all.", "Charming, humorous traditional Dutch idioms.")
                else -> CurriculumLessonContent("Er-constructies en voorzetselbijwoorden", "Er-constructions and pronominal adverbs", "ehr kohn-STROOK-tsees", "We hebben er lang over nagedacht.", "We thought about it for a long time.", "The particle 'er' has five distinct grammatical uses in Dutch.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("Watermanagement en klimaatadaptatie", "Water management and climate adaptation", "VAH-ter-mah-nahzh-ment", "De Deltawerken beschermen het laaggelegen land tegen de zee.", "The Delta Works protect low-lying land from the sea.", "The Dutch are world leaders in flood control and water engineering.")
                "Debate & Opinions" -> CurriculumLessonContent("Ik ben het daar niet mee eens", "I do not agree with that", "ik ben het dahr neet may ayns", "Ik begrijp uw standpunt, maar de feiten wijzen in een andere richting.", "I understand your position, but facts point in a different direction.", "Direct and frank debate delivered with mutual respect.")
                "Abstract Topics" -> CurriculumLessonContent("Spinoza en de Verlichting", "Spinoza and the Enlightenment", "spee-NOH-zah", "Baruch Spinoza legde in Amsterdam de fundamenten voor het vrije denken.", "Baruch Spinoza laid foundations for free thought in Amsterdam.", "The Dutch Golden Age pioneered intellectual tolerance.")
                "Natural Expressions" -> CurriculumLessonContent("Met de neus in de boter vallen", "Fall with nose in butter (have tremendous stroke of luck)", "met duh noos", "Zij viel met haar neus in de boter met die geweldige baan.", "She struck absolute gold with that fantastic job offer.", "Picturesque idiom describing fortunate luck.")
                "Listening Comprehension" -> CurriculumLessonContent("Volgen van universitaire debatten", "Following university debates", "pah-droh-NAHN-zah", "Moeiteloos complexe academische lezingen en discussies volgen.", "Effortlessly following complex academic lectures and debates.", "Listening to rapid native Dutch speech without pauses.")
                else -> CurriculumLessonContent("Het schrijven van een betoog", "Writing an argumentative essay", "buh-TOHKH", "Een overtuigend betoog met heldere argumenten en weerleggingen.", "A persuasive essay with clear arguments and rebuttals.", "Standard Dutch secondary and university essay format.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("Strategische besluitvorming en beleid", "Strategic decision-making and policy", "strah-TAY-khees", "Een integrale aanpak is vereist om deze uitdaging aan te gaan.", "An integrated approach is required to tackle this challenge.", "Executive management and governance vocabulary.")
                "Cultural Context" -> CurriculumLessonContent("De Gouden Eeuw en schilderkunst", "The Dutch Golden Age and painting", "KHOW-den ay-oo", "Rembrandt, Vermeer en Frans Hals brachten het licht tot leven.", "Rembrandt, Vermeer, and Frans Hals brought light to life.", "Artistic heritage provides cultural depth.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("Veelzijdig, doeltreffend en pragmatisch", "Versatile, effective, and pragmatic", "vayl-ZY-dikh / dool-TREF-fend", "Zijn pragmatische aanpak leidde tot een doeltreffende oplossing.", "His pragmatic approach led to an effective solution.", "Elevated adjectives enrich formal prose.")
                "Advanced Listening" -> CurriculumLessonContent("Regionale accenten en dialecten", "Regional accents and dialects", "ahk-SEN-ten", "Brabantse, Friese en Vlaamse intonaties feilloos onderscheiden.", "Flawlessly distinguishing Brabant, Frisian, and Flemish intonations.", "Appreciating Dutch spoken in Flanders and varied provinces.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("U-vorm versus je-vorm", "Polite 'U' versus casual 'Je'", "oo-vorm / yuh-vorm", "De juiste balans tussen zakelijke distantie en toegankelijkheid.", "The correct balance between professional distance and approachability.", "Modern Dutch society is egalitarian yet maintains professional decorum.")
                else -> CurriculumLessonContent("Inversie en tangconstructies", "Inversion and bracket sentence structures", "TANG-kohn-strook-tsees", "De minister heeft gisteren na lang beraad het besluit goedgekeurd.", "Yesterday after long deliberation, the minister approved the decree.", "Separating auxiliaries and infinitives creates bracket structures.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("Internationale arbitrage in Den Haag", "International arbitration in The Hague", "ahr-bee-TRAH-zhuh", "Het Vredespaleis in Den Haag herbergt het Internationaal Gerechtshof.", "The Peace Palace in The Hague houses the International Court of Justice.", "The Hague is recognized globally as the legal capital of the world.")
                "Advanced Reading" -> CurriculumLessonContent("Multatuli en Harry Mulisch", "Multatuli and Harry Mulisch literature", "MOOL-tah-too-lee", "Max Havelaar legde koloniale misstanden met vlijmscherpe pen bloot.", "Max Havelaar exposed colonial abuses with a razor-sharp pen.", "Reading acclaimed Dutch literary masterworks.")
                "Idioms & Expressions" -> CurriculumLessonContent("Spijkers op laag water zoeken", "Searching for nails at low tide (nitpicking)", "SPY-kers ohp lahkh VAH-ter", "Laten we constructief blijven en geen spijkers op laag water zoeken.", "Let's stay constructive and not nitpick insignificant trivialities.", "Traditional maritime idiom advising constructive focus.")
                "Advanced Writing" -> CurriculumLessonContent("Wetenschappelijk essay en proefschrift", "Scientific dissertation and monograph", "VAY-ten-skhahp-pruh-lik", "Gefundeerd wetenschappelijk onderzoek met rigoureuze methodologie.", "Well-grounded scientific research with rigorous methodology.", "Scholarly publication standards.")
                "Difficult Listening" -> CurriculumLessonContent("Parlementaire debatten in de Tweede Kamer", "Parliamentary debates in the House of Representatives", "TWAY-duh KAH-mer", "Vlijmscherpe interrupties en politiek steekspel direct begrijpen.", "Instantly understanding razor-sharp interruptions and political jousts.", "Real-time comprehension of rapid political debate.")
                else -> CurriculumLessonContent("Spreekvaardigheid op moedertaalniveau", "Speaking proficiency at native level", "sprayk-VAHR-dikh-heyt", "Vloeiend, gevat en stijlvast debatteren over elk onderwerp.", "Debating fluently, wittily, and stylistically consistent on any subject.", "Effortless bilingual fluency.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("Natuurlijke welbespraaktheid en flair", "Natural eloquence and communicative flair", "vel-buh-SPRAHKT-heyt", "Het gesprek verloopt met ontspannen humor en vanzelfsprekendheid.", "The conversation proceeds with relaxed humor and instinctive ease.", "Native cadence and rhythm.")
                "Humor & Cultural References" -> CurriculumLessonContent("Nederlands cabaret en zelfspot", "Dutch cabaret and self-deprecating irony", "kah-bah-RET", "De maatschappijkritische humor en satire van het cabaret doorgronden.", "Fathoming the socially critical humor and satire of Dutch cabaret.", "Cabaret represents the peak of Dutch cultural wit.")
                "Advanced Debates" -> CurriculumLessonContent("Overtuigende welsprekendheid", "Commanding eloquence and persuasion", "vel-SPRAY-kend-heyt", "Met scherpe logica en charme een zaal volledig voor zich winnen.", "Winning over an entire auditorium with sharp logic and charm.", "Mastery over public oratory.")
                "Professional Fluency" -> CurriculumLessonContent("Leiderschap in internationale handel", "Leadership in international commerce", "LAY-der-skhahp", "Moeiteloos leidinggeven aan multinationale handelsmissies.", "Effortlessly leading multinational trade missions in Dutch.", "Executive corporate leadership.")
                "Native-Speed Listening" -> CurriculumLessonContent("Feilloze auditieve intuïtie", "Flawless auditory intuition", "FEY-lohs", "Zelfs het snelste straattaal of dialect feilloos verstaan.", "Understanding even the fastest street slang or dialect without error.", "Total acoustic mastery.")
                else -> CurriculumLessonContent("Volledige integratie in de Nederlandse cultuur", "Complete cultural integration in the Netherlands", "in-tuh-KHRAH-tsee", "Volledig thuis zijn in de Nederlandse mentaliteit, humor en taal.", "Feeling completely at home in the Dutch mindset, humor, and language.", "Total cultural and linguistic harmony.")
            }
        }
    }
}

object SwedishCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("Hej! / God morgon / Hejsan", "Hello! / Good morning / Hi there", "hey / goh MOR-ohn / HEY-sahn", "Hej! Hur mår du idag?", "Hello! How are you doing today?", "'Fika' is Sweden's world-famous social coffee and pastry break.")
                "Introducing Yourself" -> CurriculumLessonContent("Jag heter Erik, trevligt att träffas", "My name is Erik, nice to meet you", "yah HEE-ter EH-reek, TRAYV-leet", "Jag heter Erik och jag kommer från Stockholm.", "My name is Erik and I come from Stockholm.", "'Trevligt att träffas' is the warm Swedish introduction response.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("Ja / Nej / Tack så mycket / Snälla", "Yes / No / Thank you very much / Please", "yah / nay / tahk soh MIK-keh / SNEHL-lah", "Ja, tack så mycket för hjälpen!", "Yes, thank you very much for the help!", "Swedes say 'tack' constantly: 'Tack så mycket', 'Tack tack'.")
                "Numbers 1–10" -> CurriculumLessonContent("Ett, två, tre, fyra, fem...", "1 to 10 numerals", "et, tvoh, tray, FEE-rah, fem", "Två koppar kaffe och en kanelbulle, tack.", "Two cups of coffee and a cinnamon bun, please.", "Cinnamon buns (kanelbulle) are the soul of Swedish baking.")
                "Basic Pronouns" -> CurriculumLessonContent("Jag, du, han, hon, den, det, vi, ni, de", "I, you, he, she, it, we, you all, they", "yah, doo, hahn, hohn, den, day, vee, nee, dohhm", "Vi lär oss svenska tillsammans varje dag.", "We are learning Swedish together every day.", "'De' (they) is pronounced 'dom' in spoken Swedish.")
                else -> CurriculumLessonContent("Ursäkta och Hej då", "Excuse me / Pardon and Goodbye", "OOR-shehk-tah / hey DOH", "Ursäkta, var ligger tunnelbanestationen?", "Excuse me, where is the subway station located?", "'Hej då' is the universal friendly farewell.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("Familjen (föräldrar, bror, syster)", "Family (parents, brother, sister)", "fah-MEEL-yen", "Min bror bor i Göteborg och min syster i Uppsala.", "My brother lives in Gothenburg and my sister in Uppsala.", "Swedish nouns belong to 'en' (common) or 'ett' (neuter) gender.")
                "Colors" -> CurriculumLessonContent("Röd, blå, gul, grön, vit", "Red, Blue, Yellow, Green, White", "rohd, bloh, gool, groen, veet", "Den svenska flaggan är blå och gul.", "The Swedish flag is blue and yellow.", "Adjectives take -t with ett-words: 'ett rött hus' (a red house).")
                "Food" -> CurriculumLessonContent("Köttbullar, lax och knäckebröd", "Meatballs, salmon, and crispbread", "SHOET-bool-lahr, lahks", "Köttbullar med potatismos och lingonsylt är en klassiker.", "Meatballs with mashed potatoes and lingonberry jam is a classic.", "Lingonberry jam accompanies savory Swedish comfort food.")
                "Days & Months" -> CurriculumLessonContent("Måndag till söndag", "Monday to Sunday", "MOHN-dahg til SOEN-dahg", "På lördag ska vi fika på ett mysigt café.", "On Saturday we will have fika at a cozy café.", "Use 'på' with days of the week: 'på måndag'.")
                "Simple Questions" -> CurriculumLessonContent("Vem? Vad? Var? När? Varför?", "Who? What? Where? When? Why?", "vem, vahd, vahr, nayr, VAHR-foer", "Varför studerar du det vackra svenska språket?", "Why do you study the beautiful Swedish language?", "In Swedish main clauses, the verb is always in the second position (V2 rule).")
                else -> CurriculumLessonContent("Äta, dricka, gå, komma", "Eat, drink, walk/go, come", "EH-tah, DREEK-kah, goh, KOHM-mah", "Ska vi gå och ta en fika tillsammans?", "Shall we go and grab a fika together?", "Irregular past tense (åt, drack, gick, kom).")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("Vakna tidigt och åka till jobbet", "Waking up early and commuting to work", "VAHK-nah TEE-deekt", "Jag vaknar klockan sju och cyklar till jobbet.", "I wake up at seven and cycle to my work.", "Compound words are written as single words in Swedish: 'tunnelbana'.")
                "Shopping" -> CurriculumLessonContent("Hur mycket kostar det här?", "How much does this cost?", "hoor MIK-keh KOHS-tahr", "Ursäkta, hur mycket kostar den här varma tröjan?", "Excuse me, how much does this warm sweater cost?", "Sweden is largely cashless; card payment ('kortbetalning') is standard.")
                "Time" -> CurriculumLessonContent("Vad är klockan nu?", "What time is it right now?", "vahd ayr KLOHK-kahn", "Klockan är halv tre på eftermiddagen.", "It is half three (2:30) in the afternoon.", "Like Dutch and German, 'halv tre' means 2:30 (halfway to 3).")
                "Directions" -> CurriculumLessonContent("Gå rakt fram och sväng till höger", "Go straight ahead and turn right", "goh rahkt frahm / svehn til HOE-ger", "Gå rakt fram två kvarter och sväng sedan till vänster.", "Go straight for two blocks and then turn left.", "'Höger' is right, 'vänster' is left.")
                "Simple Sentences" -> CurriculumLessonContent("Jag skulle vilja boka en tågbiljett", "I would like to book a train ticket", "yah SKOOL-leh VEEL-yah", "Jag skulle vilja ha ett fönsterbord på restaurangen.", "I would like a window table at the restaurant.", "'Jag skulle vilja ha' is the polite way to request.")
                else -> CurriculumLessonContent("Läget? Hur är det med dig?", "How's things? How are you doing?", "LEH-get / hoor ayr day", "Allt är bra, tack! Själv då?", "Everything is good, thanks! What about yourself?", "Classic relaxed Swedish greeting.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("Igår besökte jag Vasamuseet", "Yesterday I visited the Vasa Museum", "ee-GOHR beh-SOEK-teh yah", "Igår beundrade vi det fantastiska 1600-talsskeppet.", "Yesterday we admired the fantastic 17th-century ship.", "The Vasa is the world's only preserved 17th-century ship.")
                "Future Plans" -> CurriculumLessonContent("Jag ska resa till Lappland nästa vinter", "I will travel to Lapland next winter", "yah skah REH-sah", "I sommar ska vi hyra en stuga i skärgården.", "This summer we will rent a cottage in the archipelago.", "'Ska + infinitive' denotes future plans.")
                "Travel" -> CurriculumLessonContent("SJ-tåget och Stockholms skärgård", "SJ train and Stockholm archipelago", "es-yee TOH-get", "Snabbtåget till Malmö avgår från spår tre.", "The high-speed train to Malmö departs from track three.", "Stockholm's archipelago boasts over 30,000 islands.")
                "Restaurants" -> CurriculumLessonContent("Kan vi få notan, tack?", "May we have the bill, please?", "kahn vee foh NOH-tahn", "Maten var jättegod, kan vi få notan tack?", "The food was super delicious; may we have the bill please?", "Prefix 'jätte-' (giant) is ubiquitous in informal Swedish: 'jättebra'.")
                "Describing People" -> CurriculumLessonContent("Vänlig, pålitlig och lugn", "Friendly, reliable, and calm", "VEN-leeg, POH-leet-leeg, loongn", "Min kollega är otroligt pålitlig och hjälpsam.", "My colleague is incredibly reliable and helpful.", "Swedes value modesty and steadiness.")
                else -> CurriculumLessonContent("Vilket härligt väder idag!", "What lovely weather today!", "VEEL-ket HAYR-leekt VAY-der", "Solen skiner och det är perfekt för en promenad i skogen.", "The sun is shining; perfect for a walk in the forest.", "The Swedish legal right to roam ('Allemansrätten') permits enjoying all nature.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("Får jag lägga till en synpunkt?", "May I add a perspective?", "fohr yah LEHG-gah til", "Får jag bara flika in med en kort reflektion?", "May I briefly chip in with a quick reflection?", "'Flika in' is a natural Swedish conversational expression.")
                "Opinions" -> CurriculumLessonContent("Enligt min mening / Enligt mig", "In my opinion / According to me", "AYN-leekt meen MAY-ning", "Enligt min mening är jämställdhet grunden för ett gott samhälle.", "In my opinion, gender equality is the foundation of a good society.", "'Enligt min mening' introduces reasoned viewpoints.")
                "Experiences" -> CurriculumLessonContent("Att se norrskenet i Abisko", "Seeing the Northern Lights in Abisko", "NOR-shay-net", "Att uppleva det magiska norrskenet var en dröm som gick i uppfyllelse.", "Experiencing the magical Aurora Borealis was a dream come true.", "Abisko National Park is renowned for clear aurora skies.")
                "Comparisons" -> CurriculumLessonContent("Mycket bättre än / Lika bra som", "Much better than / Just as good as", "MIK-keh BET-treh ayn", "Tåget är betydligt mer miljövänligt än flyget.", "The train is significantly more eco-friendly than flying.", "Use 'än' for comparatives, 'som' for equality.")
                "More Complex Grammar" -> CurriculumLessonContent("Bisatser med Eftersom och Att", "Subordinate clauses with Because and That", "BEE-saht-ser", "Jag lär mig svenska eftersom jag vill arbeta i Norden.", "I am learning Swedish because I want to work in the Nordic region.", "In subordinate clauses, sentence adverbs like 'inte' come before the verb (BIFF rule).")
                else -> CurriculumLessonContent("Träna svensk hörförståelse", "Practicing Swedish listening comprehension", "HOER-foer-stoh-el-seh", "Lyssna på Sveriges Radio för att fånga språkets melodi.", "Listening to Swedish Radio to absorb the tonal melody of the language.", "Swedish has pitch accent (Accent 1 and Accent 2 tones).")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("Det var en gång för länge sedan...", "Once upon a time long ago...", "day vahr ayn gohng", "Astrid Lindgrens sagovärld berör hjärtan över hela världen.", "Astrid Lindgren's fairy-tale world touches hearts worldwide.", "Pippi Longstocking and Ronja the Robber's Daughter are Swedish treasures.")
                "Workplace Conversations" -> CurriculumLessonContent("Mötet och den platta organisationen", "The meeting and flat corporate hierarchy", "MOE-tet", "Vi diskuterar projektets milstolpar öppet i arbetslaget.", "We openly discuss project milestones within the team.", "Swedish workplaces feature flat hierarchies and consensus decisions.")
                "Social Situations" -> CurriculumLessonContent("Tack för senast och tack för maten", "Thank you for the recent time / Thanks for food", "tahk foer SAY-nahst", "Tack för senast! Vi hade så trevligt hemma hos er.", "Thank you for last time! We had such a lovely time at your home.", "'Tack för senast' is polite etiquette said when meeting a host again.")
                "News & Media" -> CurriculumLessonContent("Dagens Nyheter och ledarartiklar", "Daily news and editorial articles", "DAH-gens NY-hay-ter", "Tidningen granskar de senaste klimatpolitiska besluten.", "The newspaper examines the latest climate policy decisions.", "Journalistic Swedish is concise and objective.")
                "Idiomatic Expressions" -> CurriculumLessonContent("Lagom är bäst / Ingen ko på isen", "Moderation is best / No cow on the ice (no danger)", "LAH-gohm ayr bayst", "Oroa dig inte, det är ingen ko på isen.", "Don't worry, there is no cow on the ice (there's no danger).", "'Lagom' (not too little, not too much; just right) defines Swedish ethos.")
                else -> CurriculumLessonContent("Partikelverb i vardagsspråket", "Particle verbs in everyday speech", "pahr-TEE-kel-verb", "Vi måste ta reda på sanningen och ge upp gamla vanor.", "We must find out the truth and give up old habits.", "Stress the particle in Swedish particle verbs: 'hålla MED' (agree).")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("Den nordiska välfärdsmodellen", "The Nordic welfare model", "VEL-fayrds-moh-del-len", "Balansen mellan universell välfärd och ekonomisk konkurrenskraft.", "The balance between universal welfare and economic competitiveness.", "Debating social democracy and governance in cultured Swedish.")
                "Debate & Opinions" -> CurriculumLessonContent("Jag delar inte den uppfattningen", "I do not share that perception", "OOP-faht-neeng-en", "Jag respekterar ditt resonemang, men ser andra perspektiv.", "I respect your reasoning, but see other perspectives.", "Civil, egalitarian disagreement.")
                "Abstract Topics" -> CurriculumLessonContent("Sekularisering och tillit i samhället", "Secularization and social trust in society", "TEEL-leet", "Hög mellanmänsklig tillit är en hörnsten i det svenska samhället.", "High interpersonal trust is a cornerstone of Swedish society.", "Sweden consistently ranks among societies with highest social trust.")
                "Natural Expressions" -> CurriculumLessonContent("Att ana ugglor i mossen / Ha is i magen", "Sense owls in the moss (suspect foul play) / Ice in stomach", "OOH-glahr ee MOHS-sen", "I tuffa förhandlingar måste man ha is i magen.", "In tough negotiations, one must keep ice in one's stomach (stay cool).", "Vivid traditional idioms.")
                "Listening Comprehension" -> CurriculumLessonContent("Att följa akademiska debatter och föreläsningar", "Following academic debates and lectures", "FOER-eh-leys-neeng-ahr", "Att utan ansträngning uppfatta snabb och nyanserad argumentation.", "Effortlessly comprehending rapid and nuanced argumentation.", "Comprehending rapid spoken Swedish speech without gap.")
                else -> CurriculumLessonContent("Att skriva en argumenterande text", "Writing an argumentative essay", "ahr-gyoo-men-TAY-rahn-deh", "Att bygga upp tes och motargument med saklig skärpa.", "Building up a thesis and counterarguments with factual sharpness.", "Standard Swedish gymnasium essay framework.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("Strategisk framtidsplanering och innovation", "Strategic future planning and innovation", "strah-TEY-geesk", "Det krävs ett proaktivt förhållningssätt till grön omställning.", "A proactive approach to the green transition is required.", "Executive sustainability and innovation vocabulary.")
                "Cultural Context" -> CurriculumLessonContent("August Strindberg och Ingmar Bergman", "August Strindberg and Ingmar Bergman", "STREEND-bary / BARY-mahn", "Bergmans filmer utforskade existentiell ensamhet och tro.", "Bergman's films explored existential solitude and faith.", "Literary and cinematic milestones.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("Mångfacetterad, pregnant och sublim", "Multifaceted, pregnant with meaning, and sublime", "mohng-fah-set-TEY-rahd", "Hennes analys var ovanligt skarp och mångfacetterad.", "Her analysis was unusually sharp and multifaceted.", "High-register adjectives enrich formal speech.")
                "Advanced Listening" -> CurriculumLessonContent("Regionala dialekter i Sverige och Finland", "Regional dialects in Sweden and Finland", "dee-ah-LEK-ter", "Skånska, göteborgska, norrländska och finlandssvenska.", "Skåne, Gothenburg, Norrland, and Finland Swedish accents.", "Appreciating the rich dialectal landscape of the North.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("Du-reformen och det moderna tilltalet", "The 'Du' reform and modern egalitarian address", "DOO-reh-for-men", "Du-reformen på 1960-talet demokratiserade det svenska språket.", "The 1960s 'Du' reform democratized address across all social classes.", "Swedes address prime ministers and professors simply as 'du'.")
                else -> CurriculumLessonContent("Passivbildning med s-form och particip", "Passive voice with s-suffix and participles", "PAHS-seev", "Beslutet fattades efter noggranna överväganden.", "The decision was made ('fattades') after careful considerations.", "The -s passive suffix is clean and characteristically Scandinavian.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("Nobelpriset och internationell diplomati", "The Nobel Prize and international diplomacy", "noh-BEL-pree-set", "Nobelpriset i Stockholm och fredspriset i Oslo förenar världen.", "The Nobel Prize in Stockholm and Peace Prize in Oslo unite the world.", "Diplomatic and scientific Swedish.")
                "Advanced Reading" -> CurriculumLessonContent("Karin Boye och Tomas Tranströmer", "Karin Boye and Tomas Tranströmer poetry", "BOY-eh / TRAHN-stroe-mer", "Tranströmers nobelprisbelönta poesi präglas av förtätade metaforer.", "Tranströmer's Nobel-winning poetry is defined by concentrated metaphors.", "Appreciating universally celebrated Swedish verse.")
                "Idioms & Expressions" -> CurriculumLessonContent("Skilja agnarna från vetet", "Separate the chaff from the wheat", "SHEEL-yah AHNG-nahr-nah", "Krisen satte organisationen på prov och skilde agnarna från vetet.", "The crisis tested the organization and separated the chaff from wheat.", "Biblical and agricultural idioms in Swedish.")
                "Advanced Writing" -> CurriculumLessonContent("Vetenskaplig avhandling och essä", "Scientific dissertation and scholarly essay", "VEH-ten-skahp-leeg", "Att producera en doktorsavhandling med vetenskaplig integritet.", "Producing a doctoral dissertation with scientific integrity.", "Scholarly publication standards.")
